/*
 * A045347  Primes congruent to {0, 2, 4, 5, 6} mod 7.
 * https://oeis.org/A045347
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 36, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   grow_seq, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Computation of sequence A045347:
 *  a(n) = the n-th prime that is ≡ 0, 2, 4, 5, or 6 (mod 7).
 *  The sequence is generated by a simple linear search with caching,
 *  using the provided primality test is_prime_big().
 *  No hard‑coded values are used; the function works for any
 *  n ≥ 1, in any order of calls, and returns exact results
 *  while keeping intermediate values bounded.
 */
#include <stdbool.h>
#include <stddef.h>
#include "../utils/grow_seq.h"
#include "../utils/is_prime_big.h"

static seq_t *cache   = NULL;   /* cached list of qualifying primes   */
static size_t cache_len = 0;    /* number of cached terms             */
static size_t cache_cap = 0;    /* current capacity of the cache      */
static seq_t next_candidate = 2;/* next integer to test for primality */

seq_t a(idx_t n)
{
    /* safety: OEIS offset is 1; behaviour for n==0 is irrelevant   */
    if (n == 0) return 0;

    /* Build up the cache until it contains at least n terms.       */
    while (cache_len < n) {
        seq_t q = next_candidate;

        if (is_prime_big(q)) {
            seq_t r = q % (seq_t)7UL;                 /* remainder mod 7 */
            if (r != (seq_t)1 && r != (seq_t)3) {    /* residues 0,2,4,5,6 */
                /* Ensure capacity to store one more element.    */
                size_t needed = cache_len + 1;
                if (needed > cache_cap) {
                    grow_seq(&cache, &cache_cap, needed);
                }
                cache[cache_len++] = q;
            }
        }
        /* Advance to the next integer.  The sequence is monotone
           and the search is exhaustive, guaranteeing correct results. */
        next_candidate++;
    }
    return cache[n - 1];
}
